def has_short_cycle(edge_set, n):
    # Check if graph has cycle of length 3,4,5,6
    # Use BFS from each vertex up to depth 3 (for cycles up to 6)
    adj = [set() for _ in range(n)]
    for u, v in edge_set:
        adj[u].add(v)
        adj[v].add(u)

    # Check cycles of length 3
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > u and w != u and u in adj[w]:
                        return True

    # Check cycles of length 4
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w != u and w != v:
                        for x in adj[w]:
                            if x > u and x != v and x != w and x in adj[u]:
                                # Ensure distinctness: u,v,w,x all distinct
                                if len({u,v,w,x}) == 4:
                                    return True

    # Check cycles of length 5
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w not in (u,v):
                        for x in adj[w]:
                            if x not in (u,v,w):
                                for y in adj[x]:
                                    if y not in (u,v,w,x) and y in adj[u]:
                                        if len({u,v,w,x,y}) == 5:
                                            return True

    # Check cycles of length 6
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w not in (u,v):
                        for x in adj[w]:
