def has_path_of_length_at_most_k(adj, u, v, k):
    """Check if there's a path from u to v of length <= k (using BFS)"""
    if u == v:
        return True
    visited = {u}
    frontier = {u}
    for dist in range(1, k+1):
        new_frontier = set()
        for node in frontier:
            for nb in adj[node]:
                if nb == v:
                    return True
                if nb not in visited:
                    visited.add(nb)
                    new_frontier.add(nb)
        frontier = new_frontier
        if not frontier:
            return False
    return False

