def get_cycles_from_edge(adj, u, v, max_len):
    """Find all cycles created by adding edge (u,v) to graph adj"""
    # BFS from u to v, looking for paths of length 2 to max_len-1
    cycles = []
    # BFS
    from collections import deque
    queue = deque([(u, [u])])
    while queue:
        node, path = queue.popleft()
        if len(path) > max_len:
            continue
        for nb in adj[node]:
            if nb == v and len(path) >= 2:
                # Found a path from u to v
                cycle_len = len(path) + 1
                if cycle_len <= max_len:
                    cycles.append(tuple(path + [v]))
            elif nb not in path:
                queue.append((nb, path + [nb]))
    return cycles

