import random

def build_bipartite_girth7(a, b, seed=None):
    """Build bipartite graph with parts of size a and b, girth >= 7"""
    n = a + b
    if seed is not None:
        random.seed(seed)

    A = list(range(a))
    B = list(range(a, a+b))

    adj = [set() for _ in range(n)]
    edges = []

    # All possible edges between A and B
    candidates = [(u, v) for u in A for v in B]
    random.shuffle(candidates)

    for u, v in candidates:
        # Check if adding (u,v) creates C4 or C6
        # C4: there exists w in A, x in B such that (u,x), (w,x), (w,v) are edges
        # C6: there exists path of length 5 from u to v

        # Check C4
        has_c4 = False
        for x in adj[u]:  # x in B
            for w in adj[x]:  # w in A
                if w != u and v in adj[w]:
                    has_c4 = True
                    break
            if has_c4:
                break

        if has_c4:
            continue

        # Check C6: path of length 5 from u to v
        # u - b1 - a1 - b2 - a2 - v
        has_c6 = False
        for b1 in adj[u]:
            for a1 in adj[b1]:
                if a1 == u:
                    continue
                for b2 in adj[a1]:
                    if b2 == b1:
                        continue
                    for a2 in adj[b2]:
                        if a2 == a1 or a2 == u:
                            continue
                        if v in adj[a2]:
                            has_c6 = True
                            break
                    if has_c6:
                        break
                if has_c6:
                    break
            if has_c6:
                break

        if not has_c6:
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u, v))

    return edges

